/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/breadcrumb.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
import * as React from "react";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import { Slot } from "radix-ui";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Breadcrumb({
  ...props
}: React.ComponentProps<"nav"> & CapconsBasePropsLoose) {
  return <nav aria-label="breadcrumb" data-slot="breadcrumb" {...capconsSpread(props)} />;
}
function BreadcrumbList({
  className,
  ...props
}: React.ComponentProps<"ol"> & CapconsBasePropsLoose) {
  return <ol data-slot="breadcrumb-list" className={cn("flex flex-wrap items-center gap-1.5 text-sm break-words text-muted-foreground sm:gap-2.5", className)} {...capconsSpread(props)} />;
}
function BreadcrumbItem({
  className,
  ...props
}: React.ComponentProps<"li"> & CapconsBasePropsLoose) {
  return <li data-slot="breadcrumb-item" className={cn("inline-flex items-center gap-1.5", className)} {...capconsSpread(props)} />;
}
function BreadcrumbLink({
  asChild,
  className,
  ...props
}: React.ComponentProps<"a"> & {
  asChild?: boolean;
} & CapconsBasePropsLoose) {
  const Comp = asChild ? Slot.Root : "a";
  return <Comp data-slot="breadcrumb-link" className={cn("transition-colors hover:text-foreground", className)} {...capconsSpread(props)} />;
}
function BreadcrumbPage({
  className,
  ...props
}: React.ComponentProps<"span"> & CapconsBasePropsLoose) {
  return <span data-slot="breadcrumb-page" role="link" aria-disabled="true" aria-current="page" className={cn("font-normal text-foreground", className)} {...capconsSpread(props)} />;
}
function BreadcrumbSeparator({
  children,
  className,
  ...props
}: React.ComponentProps<"li"> & CapconsBasePropsLoose) {
  return <li data-slot="breadcrumb-separator" role="presentation" aria-hidden="true" className={cn("[&>svg]:size-3.5", className)} {...capconsSpread(props)}>
      {children ?? <ChevronRight />}
    </li>;
}
function BreadcrumbEllipsis({
  className,
  ...props
}: React.ComponentProps<"span"> & CapconsBasePropsLoose) {
  return <span data-slot="breadcrumb-ellipsis" role="presentation" aria-hidden="true" className={cn("flex size-9 items-center justify-center", className)} {...capconsSpread(props)}>
      <MoreHorizontal className="size-4" />
      <span className="sr-only">More</span>
    </span>;
}
export { Breadcrumb, BreadcrumbList, BreadcrumbItem, BreadcrumbLink, BreadcrumbPage, BreadcrumbSeparator, BreadcrumbEllipsis };
